#!/usr/bin/env python3
"""
siz_delimiter_server.py — MCP JSON-RPC server para o siz_delimiter helenizado.

HELENIZADO 2026-08-11: expõe o siz_delimiter (harness/core/siz_delimiter.py)
como ferramenta MCP (stdio), padrão compatível com o obsidian_server.py já
existente no harness (JSON-RPC 2.0, lote por newline).

Ferramentas expostas:
  siz_delimit         — gera siz_inventory (skeleton estrutural) para Fase 1
  siz_parse_symbols   — extrai símbolos de um arquivo (com cache SQLite)
  siz_health          — health check (endpoint tokenizer + cache dir)

Uso: python3 harness/mcp/siz_delimiter_server.py
Registrar no opencode.json como MCP stdio.
"""

from __future__ import annotations

import json
import sys
import traceback
from pathlib import Path

# Garante import do core em qualquer cwd de invocação
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from core.siz_delimiter import (  # noqa: E402
    CACHE_DIR,
